import { FormatToolbar, Card, Badge, Button } from "march/ui"
import { bold as boldIcon } from "march/icons"
import type { FormatTool } from "march/ui"

// FormatToolbar'ın bütün özellikleri: araç listesi ve ayırıcı, onTool, çubuğun adı (canlı), araç adları (labels ve
// name işlevi), kendi ikonları (false: ikonsuz), tek tek devre dışı, aç / kapa (pressed), kısayollar (keys),
// ipucunda kısayol (hints), boyut, sınıf öneki (prefix), düğmeye ek öznitelikler (attrs), sınıf
export function FormatToolbarLab() {
  let $bold = false
  let $italic = true
  let $last = "yok"
  let $count = 0
  let $big = false
  const run = (tool: FormatTool) => {
    if (tool === "bold") $bold = !$bold
    if (tool === "italic") $italic = !$italic
    $last = tool
    $count++
  }
  return <div sx={{ flex: "col", gap: 3 }}>
    <FormatToolbar tools={["bold", "italic", "strike", "|", "link", "code", "|", "undo", "redo"]} onTool={run}
      label={() => `Biçim (${$count})`} labels={() => ({ bold: $bold ? "Kalın: açık" : "Kalın: kapalı", italic: "Eğik" })}
      name={(tool) => (tool === "link" ? "Bağlantı ekle" : undefined)}
      icons={{ bold: boldIcon, strike: "S", code: false }} pressed={{ bold: () => $bold, italic: () => $italic }}
      disabled={(tool) => tool === "redo"} keys={{ link: "Control+L", code: false }} hints={() => $big}
      size={() => ($big ? "md" : "sm")} prefix="lab" class="lab-bar"
      attrs={(tool) => (tool === "link" ? { "aria-haspopup": "dialog", class: "lab-link" } : {})} />
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Badge tone="neutral">{`Son araç: ${$last}`}</Badge>
      <Button size="sm" variant="secondary" on:click={() => $big = !$big}>{$big ? "Küçült" : "Büyüt (ipucunda kısayol)"}</Button>
    </div>
    <Card m:theme="night">
      <FormatToolbar tools={["h2", "h3", "|", "ul", "ol", "task", "quote"]} onTool={run} disabled label="Kapalı çubuk" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { FormatToolbarLab } from "./FormatToolbarLab.tsx"

// FormatToolbarLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Kalın'a basınca basılı olur, adı ve çubuğun adı canlı değişir", async () => {
  const s = renderTest(() => <FormatToolbarLab />)
  const b = await s.click("Kalın: kapalı")
  expect(b.getAttribute("aria-pressed")).toBe("true")
  expect(b.getAttribute("aria-label")).toBe("Kalın: açık")
  expect(s.find("Biçim (1)")?.getAttribute("role")).toBe("toolbar")
  expect(s.sees("Son araç: bold")).toBe(true)
})

test("name işlevi, keys, attrs ve prefix bağlantı düğmesine yazılır", () => {
  const s = renderTest(() => <FormatToolbarLab />)
  const link = s.find("Bağlantı ekle")
  expect(link?.getAttribute("aria-keyshortcuts")).toBe("Control+L")
  expect(link?.getAttribute("aria-haspopup")).toBe("dialog")
  expect(link?.className).toContain("lab-tool")
  expect(link?.className).toContain("lab-link")
  expect(s.get(".lab-bar")?.className).toContain("lab-toolbar")
})

test("redo tek başına, ikinci çubuk tümüyle devre dışı", () => {
  const s = renderTest(() => <FormatToolbarLab />)
  expect(s.get(".lab-bar")?.querySelectorAll("button[disabled]").length).toBe(1)
  const off = s.find("Kapalı çubuk")?.querySelectorAll("button") ?? []
  expect([...off].every((b) => b.hasAttribute("disabled"))).toBe(true)
})

test("Büyüt ipucuna kısayolu ekler", async () => {
  const s = renderTest(() => <FormatToolbarLab />)
  expect(s.find("Eğik")?.getAttribute("title")).toBe("Eğik")
  await s.click("Büyüt (ipucunda kısayol)")
  expect(s.find("Eğik")?.getAttribute("title")).not.toBe("Eğik")
})
